mapper.select:
WITH RECURSIVE descendants AS (SELECT m.id, m.code, m.name, m.parent_id, m.level, m.type, m.sort, m.status, m.manager, m.phone, m.address, m.description, m.properties, m.create_time, m.update_time, m.create_by, m.update_by FROM mdm_factory_model m WHERE m.id = #{nodeId} and m.del_flag = '0'
UNION ALL
SELECT f.id, f.code, f.name, f.parent_id, f.level, f.type, f.sort, f.status, f.manager, f.phone, f.address, f.description, f.properties, f.create_time, f.update_time, f.create_by, f.update_by FROM mdm_factory_model f INNER JOIN descendants d ON f.parent_id = d.id and f.del_flag = '0') SELECT * FROM descendants WHERE id != #{nodeId}

SELECT COUNT(*)
FROM mdm_factory_model
WHERE code = #{code}

    AND id != #{excludeId}

and del_flag = '0'
